class Solution:
    def minNumberOfSemesters(self, n, dependencies, k):
        reqs = [0]*n
        for u, v in dependencies:
            reqs[v-1] |= 1 << (u-1)
        dp = [n]*(1<<n)
        dp[0] = 0
        for mask in range(1<<n):
            candidates = []
            for v in range(n):
                if (mask&(1<<v)) == 0 and (mask&reqs[v]) == reqs[v]:
                    candidates.append(v)
            for choice in itertools.combinations(candidates, min(len(candidates), k)):
                new_mask = mask
                for v in choice:
                    new_mask |= 1<<v
                dp[new_mask] = min(dp[new_mask], dp[mask]+1)
        return dp[-1]

class Solution:
    def isPathCrossing(self, path: str) -> bool:
        c = set()
        x,y = 0,0
        c.add((x,y))
        for i in path:
            if i == 'N':
                y+=1
            elif i == 'E':
                x+=1
            elif i == 'W':
                x-=1
            else:
                y-=1
            if (x,y) in c:
                return True
            else:
                c.add((x,y))
        return False

class Solution:
    def isPathCrossing(self, path: str) -> bool:
        x = y = 0
        lookup = {(0, 0)}
        for c in path:
            if c == 'E':
                x += 1
            elif c == 'W':
                x -= 1
            elif c == 'N':
                y += 1
            elif c == 'S':
                y -= 1
            if (x, y) in lookup:
                return True
            lookup.add((x, y))
        return False

